INSERT INTO regole (id, nome, gravita, tipo, descrizione, parametri) VALUES
('R01', 'Portata cavo ≥ corrente interruttore', 'blocco', 'portata_cavo', 'Il cavo associato a un interruttore deve avere portata (Iz) maggiore o uguale alla corrente nominale dell''interruttore (In).', '{"condizione_posa": "cavo multipolare in tubo a parete, 30°C (semplificato)", "portata_a_per_sezione": {"2_conduttori_carichi": {"1.5": 23, "2.5": 31, "4": 42, "6": 54, "10": 75, "16": 100, "25": 133, "35": 164, "50": 198, "70": 253, "95": 306, "120": 354}, "3_conduttori_carichi": {"1.5": 20, "2.5": 28, "4": 37, "6": 48, "10": 66, "16": 88, "25": 117, "35": 144, "50": 175, "70": 222, "95": 269, "120": 312}}, "conduttori_carichi_per_poli": {"1P": 2, "1P+N": 2, "2P": 2, "3P": 3, "4P": 3}}'::jsonb),
('R02', 'Conduttori cavo sufficienti per i poli', 'blocco', 'conduttori_vs_poli', 'Un cavo multipolare deve avere almeno i conduttori attivi richiesti dai poli dell''interruttore più il conduttore di protezione (PE).', '{"conduttori_minimi_per_poli": {"1P": 3, "1P+N": 3, "2P": 3, "3P": 4, "4P": 5}}'::jsonb),
('R03', 'Sezione minima per tipo di circuito', 'avviso', 'sezione_minima_circuito', 'Sezioni minime consigliate per i circuiti terminali.', '{"sezione_min_mm2": {"illuminazione": 1.5, "prese": 2.5, "forza_motrice": 4}}'::jsonb),
('R04', 'Moduli DIN sufficienti nel centralino', 'blocco', 'capienza_quadro', 'La somma dei moduli DIN dei dispositivi assegnati a un centralino modulare non può superare i moduli disponibili.', '{"campo_moduli_dispositivo": "moduli_din", "campo_moduli_quadro": "attributi.moduli_disponibili"}'::jsonb),
('R05', 'Riserva spazio nel centralino', 'avviso', 'riserva_quadro', 'È buona pratica lasciare almeno il 20% di moduli liberi per ampliamenti futuri.', '{"riserva_min_pct": 20}'::jsonb),
('R06', 'Scatolati solo in quadri a armadio', 'blocco', 'montaggio_compatibile', 'Gli interruttori scatolati (montaggio su piastra) richiedono un quadro a armadio, non un centralino modulare.', '{"categoria_dispositivo": "scatolati", "richiede_quadro_con": {"tipo_quadro": "armadio", "accetta_scatolati": true}}'::jsonb),
('R07', 'Blocco differenziale compatibile con il magnetotermico', 'blocco', 'accoppiamento_blocco_diff', 'Un blocco differenziale va accoppiato a un magnetotermico con lo stesso numero di poli (2P con 1P+N/2P, 4P con 3P/4P) e corrente nominale non superiore alla corrente massima del blocco.', '{"poli_compatibili": {"2P": ["1P+N", "2P"], "4P": ["3P", "4P"]}}'::jsonb),
('R08', 'Potere di interruzione ≥ corrente di cortocircuito', 'blocco', 'potere_interruzione', 'Se la richiesta indica la corrente di cortocircuito presunta (Icc), ogni interruttore deve avere potere di interruzione maggiore o uguale.', '{"campo_richiesta": "icc_presunta_ka", "campo_articolo": "attributi.potere_interruzione_ka"}'::jsonb),
('R09', 'Selettività tra differenziali', 'avviso', 'selettivita_differenziali', 'Se a valle ci sono differenziali da 30mA, il differenziale generale a monte dovrebbe essere selettivo (tipo S) con sensibilità maggiore (es. 300mA).', '{"sensibilita_monte_min_ma": 300, "richiede_selettivo": true}'::jsonb),
('R10', 'Classe differenziale per carichi elettronici', 'avviso', 'classe_differenziale', 'Per circuiti con carichi elettronici (inverter, pompe di calore, piani a induzione, lavatrici) è sconsigliato il tipo AC: proporre almeno tipo A, o tipo F per carichi con inverter monofase.', '{"carichi_sensibili": ["inverter", "pompa di calore", "induzione", "lavatrice", "fotovoltaico", "colonnina"], "classe_minima": "A", "classe_consigliata_inverter": "F"}'::jsonb),
('R11', 'Grado IP per ambienti esterni', 'blocco', 'grado_ip_ambiente', 'Quadri e prese installati all''esterno o in ambienti umidi devono avere grado di protezione almeno IP55 (quadri) e IP67 (prese esposte).', '{"ip_minimo": {"quadri": 55, "prese_industriali": 67}, "ambienti": ["esterno", "umido", "cantiere"]}'::jsonb),
('R12', 'Contattore dimensionato sul carico', 'blocco', 'portata_contattore', 'La corrente AC-3 (o nominale per i modulari) del contattore deve essere maggiore o uguale alla corrente del carico comandato.', '{"campi_corrente": ["attributi.corrente_ac3_a", "attributi.corrente_a"]}'::jsonb),
('R13', 'Protezione a monte dello scaricatore', 'avviso', 'protezione_spd', 'Lo scaricatore richiede a monte una protezione con corrente nominale non superiore al valore massimo indicato dal costruttore.', '{"campo_massimo": "attributi.protezione_monte_max_a"}'::jsonb),
('R14', 'Morsetto adatto alla sezione del cavo', 'blocco', 'range_morsetto', 'La sezione del cavo deve rientrare nel range del morsetto associato.', '{"campo_min": "attributi.sezione_min_mm2", "campo_max": "attributi.sezione_max_mm2"}'::jsonb),
('R15', 'Arrotondamento alla confezione', 'avviso', 'multiplo_confezione', 'Le quantità si arrotondano per eccesso al multiplo della confezione (es. matassa da 100 m, confezione da 10 pz). Mostrare la quantità richiesta e quella fatturata.', '{"arrotondamento": "eccesso"}'::jsonb),
('R16', 'Sconto massimo per categoria', 'blocco', 'sconto_massimo', 'Il commerciale non può applicare uno sconto superiore al massimo previsto per la categoria senza approvazione.', '{"sconto_max_pct": {"cavi": 55, "magnetotermici": 50, "differenziali": 50, "magnetotermici_differenziali": 50, "blocchi_differenziali": 50, "quadri": 45, "scatolati": 40, "sezionatori": 50, "contattori": 45, "comando": 45, "scaricatori": 40, "tubi_canaline": 55, "morsetti": 50, "prese_industriali": 45, "accessori": 50}, "default": 35}'::jsonb);
